import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int Cin, const int D, const int H, const int W,
    const int Cout, const int K,
    const int stride, const int padding, const int dilation,
    const int groups,
    const int Dout, const int Hout, const int Wout,
    const bool has_bias)
{
    const int total = N * Cout * Dout * Hout * Wout;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int tmp = idx;
    const int ow = tmp % Wout; tmp /= Wout;
    const int oh = tmp % Hout; tmp /= Hout;
    const int od = tmp % Dout; tmp /= Dout;
    const int oc = tmp % Cout; tmp /= Cout;
    const int n  = tmp;

    const int Cin_per_group = Cin / groups;
    const int Cout_per_group = Cout / groups;
    const int g = oc / Cout_per_group;
    const int ic_start = g * Cin_per_group;

    float acc = 0.0f;

    const int in_batch_stride = Cin * D * H * W;
    const int in_ch_stride = D * H * W;
    const int in_d_stride = H * W;
    const int in_h_stride = W;

    const int w_oc_stride = Cin_per_group * K * K * K;
    const int w_ic_stride = K * K * K;
    const int w_kd_stride = K * K;
    const int w_kh_stride = K;

    const float* in_n = input + n * in_batch_stride;
    const float* w_oc = weight + oc * w_oc_stride;

    for (int icg = 0; icg < Cin_per_group; icg++) {
        const int ic = ic_start + icg;
        const float* in_c = in_n + ic * in_ch_stride;
        const float* w_ic = w_oc + icg * w_ic_stride;

        for (int kd = 0; kd < K; kd++) {
            const int id = od * stride - padding + kd * dilation;
            if (id < 0 || id >= D) continue;
            const float* in_d = in_c + id * in_d_stride;
            const float* w_kd = w_ic + kd * w_kd_stride;

            for (int kh = 0; kh < K; kh++) {
                const int ih = oh * stride - padding + kh * dilation;
                if (ih < 0 || ih >= H) continue;
                const float* in_h = in_d + ih * in_h_stride;
                const float* w_kh = w_kd + kh * w_kh_stride;

                for (int kw = 0; kw < K; kw++) {
                    const int iw = ow * stride - padding + kw * dilation;
                    if (iw < 0 || iw >= W) continue;
                    acc += in_h[iw] * w_kh[kw];
                }
            }
        }
    }

    if (has_bias) {
        acc += bias[oc];
    }

    output[idx] = acc;
}

torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();

    const int N = input.size(0);
    const int Cin = input.size(1);
    const int D = input.size(2);
    const int H = input.size(3);
    const int W = input.size(4);

    const int Cout = weight.size(0);
    const int K = weight.size(2);

    const int Dout = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int Wout = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, Cout, Dout, Hout, Wout}, input.options());

    const int total = N * Cout * Dout * Hout * Wout;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    conv3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, Cin, D, H, W,
        Cout, K,
        stride, padding, dilation,
        groups,
        Dout, Hout, Wout,
        has_bias
    );

    return output;
}
"""

conv3d_header = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias);
"""

conv3d_module = load_inline(
    name="conv3d_custom",
    cpp_sources=conv3d_header,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if bias:
            fan_in = in_channels // groups * kernel_size * kernel_size * kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda()
        if self.has_bias:
            bias = self.bias.cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return conv3d_module.conv3d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups,
            self.has_bias
        )

